local function reset()
  P.on, P.pending, P.shown, P.opened = false, false, false, {}
  P.cards, P.base, P.shift, P.button, P.click_prev, P.source, P.logged = {}, {}, nil, nil, false, nil, {}
  P.named, P.row = {}, nil
end
reset()

local function M(...)
  local r = table.pack(pcall(funcLuaMenuCommand, ...))
  if not r[1] then
    return nil
  end
  return table.unpack(r, 2, r.n)
end

local function F(...)
  local r = table.pack(pcall(funcLuaCommand, ...))
  if not r[1] then
    return nil
  end
  return table.unpack(r, 2, r.n)
end

local function log(...)
  pcall(funcLuaCommand, P.C.LOG, "ChronicleDeluxe.Lineup", ...)
end

local function instances(layer)
  local n = M(P.C.LAYER_NUM, layer)
  return type(n) == "number" and n or 0
end

-- the menu has the layers of content\menus\team_lineup.toml
local function layers_ready()
  return instances(P.LAYER.PITCH) >= 1 and instances(P.LAYER.CARD) >= P.STARTERS and instances(P.LAYER.TEXT) >= 2
end

-- the retail name setting of a soccer card on instance `slot` of the card layer (once per instance)
local function name_card(slot)
  if P.named[slot] or MENU_DEF == nil or MENU_DEF.NameSettingBegin == nil then
    return
  end
  P.named[slot] = true
  local ok, err = pcall(function()
    MENU_DEF.NameSettingBegin(P.LAYER.CARD, slot)
    for _, entry in ipairs(P.CARD_NAMES) do
      MENU_DEF.AddName(entry[1], entry[2])
    end
    MENU_DEF.NameSettingEnd()
  end)
  if not ok then
    log("card name setting failed", slot, tostring(err))
  end
end

P.BAND_HEIGHT = math.ceil(P.LAYOUT.TOP_GAP + P.LAYOUT.NAME_HEIGHT + P.LAYOUT.NAME_GAP
  + P.PITCH.FIELD_HEIGHT * P.LAYOUT.PITCH_SCALE_Y + P.LAYOUT.PITCH_GAP + P.LAYOUT.BUTTON_HEIGHT)

-- width of a text at scale 1 (a button tag <...> counts as two characters, a CJK glyph as two)
local function text_width(s)
  local units, i, n = 0, 1, string.len(s)
  while i <= n do
    local b = string.byte(s, i)
    if b == 60 then   -- "<"
      local close = string.find(s, ">", i, true)
      if close ~= nil then
        units = units + 2
        i = close + 1
      else
        units = units + 1
        i = i + 1
      end
    else
      local len = b >= 0xF0 and 4 or (b >= 0xE0 and 3 or (b >= 0xC0 and 2 or 1))
      units = units + (len >= 3 and 2 or 1)
      i = i + len
    end
  end
  return math.max(units, 1) * P.LABEL.CHAR_WIDTH
end

-- a slot's position from the pitch's centre (pitch px, y up): the retail rule with the pitch's locators
function P.SlotOffset(formation, slot)
  local G, R = P.PITCH, P.FORMATION
  local ok, x, _, y = F(P.C.FORMATION_INFO, 4, formation, slot, R.BASE_SET)
  if ok ~= true then
    x, y = 0, 0
  end
  x, y = x or 0, y or 0
  local total = math.abs(G.TOP_Y - G.BOTTOM_Y)
  local above = math.abs(G.CENTRE_Y - G.TOP_Y)
  local below = math.abs(G.CENTRE_Y - G.BOTTOM_Y)
  local depth = y / R.DEPTH_UNITS
  local height_here = -y * (total / R.DEPTH_UNITS) + total * 0.5
  local width_here = (G.TOP_WIDTH - G.BOTTOM_WIDTH) * (height_here / total) + G.BOTTOM_WIDTH
  local px = x * (width_here / R.WIDTH_UNITS)
  local py = below - y * (G.BOTTOM_WIDTH / R.WIDTH_UNITS)
  if depth < 0 then
    py = py + total * depth * above / below
  elseif depth > 0 then
    py = py + above * depth * below / (total * 0.5)
  end
  local okO, dx, dy = F(P.C.FORMATION_INFO, 4, formation, slot, R.OFFSET_SET)
  if okO == true then
    px = px + (dx or 0) * R.OFFSET_SCALE
    py = py + (dy or 0) * R.OFFSET_SCALE
  end
  py = py - below
  local okK, kind = F(P.C.FORMATION_INFO, 5, formation, slot)
  if okK == true and kind == 0 then
    py = py + R.KEEPER_LIFT
  end
  return px, py
end

local function formation_name(formation)
  local ok, text = F(P.C.FORMATION_INFO, 7, formation)
  if ok == true and text ~= nil then
    local name = F(P.C.TEXT_OF_ID, text)
    return type(name) == "string" and name or ""
  end
  return ""
end

-- the user's active team: formation, its name and starters {slot -> card}
function P.ReadDockTeam()
  local set = F(P.C.TEAM_SET)
  if type(set) ~= "number" then
    return nil
  end
  local okF, formation = F(P.C.TEAM_SET_INFO, set, 0, 4)
  if okF ~= true or type(formation) ~= "number" or formation == 0 then
    return nil
  end
  local okU, uniform = F(P.C.TEAM_SET_INFO, set, 0, 7)
  local team = {key = "dock:" .. set, formation = formation, name = formation_name(formation), starters = {}}
  for i = 0, P.MEMBER_SLOTS - 1 do
    local okH, handle = F(P.C.TEAM_MEMBER, set, 0, i, 0)
    local okS, slot = F(P.C.TEAM_MEMBER, set, 0, i, 1)
    if okH == true and okS == true and type(handle) == "number" and handle ~= 0 and type(slot) == "number"
        and slot >= 0 and slot < P.STARTERS then
      local okP, position = F(P.C.FORMATION_INFO, 6, formation, slot)
      local okC, captain = F(P.C.TEAM_SET_INFO, set, 0, 8, handle)
      local level = F(P.C.CHARA_INFO, handle, 0)
      position = okP == true and position or 0
      team.starters[slot] = {handle = handle, position = position, fill = {
        layerName = P.LAYER.CARD, layerIdx = slot, charaStHdl = handle, isBigCardType = true,
        isForceLeader = false, overwritePosType = position, charaFaceType = 0,
        level = type(level) == "number" and level or 0, isCaptain = okC == true and captain == true,
        uniformId = okU == true and uniform or 0, isMainMember = true, titleAttr = 0, isForceUpdateBustup = false,
        isManager = false, isGrayout = false, isDisableTeamUniform = false, rarityFrameEffectDrawType = 0,
        isTeamDockIconVisible = false, isForcePlayerUniform = true, teamSet = set, faceIconChrStHdl = 0,
        isUpdateTempAvatar = true,
      }}
    end
  end
  return team
end

-- the piece's Chronicle team (the user's side of a Batalla de crónica), read as the VS screen's SetFormation does
function P.ReadChronicleTeam(game, difficulty)
  local okT, id = F(P.C.CHRONICLE_TEAM, game, 8)
  if okT ~= true or type(id) ~= "number" or id == 0 then
    return nil
  end
  local okF, formation = F(P.C.TEAM_PARAM, id, 3)
  if okF ~= true or type(formation) ~= "number" or formation == 0 then
    return nil
  end
  local okN, count = F(P.C.TEAM_PARAM, id, 8)
  local okU, uniform = F(P.C.TEAM_PARAM, id, 4)
  local team = {key = "chronicle:" .. id, formation = formation, name = formation_name(formation), starters = {}}
  if okN ~= true or type(count) ~= "number" or GetTeamMemberInfo == nil then
    return team
  end
  for i = 0, count - 1 do
    local ok, chara, slot, level, captain, kit = GetTeamMemberInfo(id, i, game, difficulty, true)
    if ok and type(slot) == "number" and slot >= 0 and slot < P.STARTERS then
      local okP, position = F(P.C.FORMATION_INFO, 6, formation, slot)
      team.starters[slot] = {chara = chara, position = okP == true and position or 0, level = level,
        captain = captain, kit = kit, uniform = okU == true and uniform or 0}
    end
  end
  return team
end

-- the team of the focused row's battle
function P.ReadFocusedTeam()
  local L = VRFW_RBC.L
  local rows = L.t3
  local index = M(P.C.FOCUS_GET, P.ROWS)
  local row = type(rows) == "table" and type(index) == "number" and rows[index + 1] or nil
  if row ~= nil and row.difficultyType == P.CHRONICLE_DIFFICULTY and P.kind == 0 then
    local team = P.ReadChronicleTeam(L.n4, P.CHRONICLE_DIFFICULTY)
    if team ~= nil then
      return team
    end
    log("no Chronicle team for game", L.n4, "- the active team is shown")
  end
  local team = P.ReadDockTeam()
  if team ~= nil and row ~= nil then
    P.MarkOffenders(team, L.n4, L.n2, row.difficultyType or 0)
  end
  return team
end

-- the starters of the user's team that the focused row's challenge names as offenders (the same check as the VS
-- screen's kick-off gate); the team's key gets the challenge so a row with another one redraws
function P.MarkOffenders(team, game, slot, difficulty)
  if VRFW_MC == nil or difficulty <= 0 or type(game) ~= "number" then
    return
  end
  local i = VRFW_MC.Of(game, difficulty)
  if i == nil then
    return
  end
  local cleared = type(slot) == "number" and F(P.C.CLEAR_GET, slot, difficulty) == true
  local ok, _, offenders, players = pcall(VRFW_MC.Check, i, 0, cleared)
  if not ok or type(offenders) ~= "table" or type(players) ~= "table" then
    return
  end
  local bad, count = {}, 0
  for _, k in ipairs(offenders) do
    local player = players[k]
    if player ~= nil then
      bad[player.hdl] = true
    end
  end
  for _, card in pairs(team.starters) do
    if card.handle ~= nil and bad[card.handle] then
      card.offender = true
      count = count + 1
    end
  end
  team.key = team.key .. ":challenge" .. i .. ":" .. count
end

local function place(layer, k)
  local b = P.base[layer .. ":" .. k]
  if b == nil then
    return
  end
  local dx, dy = 0, 0
  if VRFW_RBC_PanelShift ~= nil then
    dx, dy = VRFW_RBC_PanelShift()
  end
  M(P.C.POS, layer, b[1] + dx, b[2] + dy, 0, k)
end

local function open(layer, k, priority)
  local key = layer .. ":" .. k
  if not P.opened[key] then
    P.opened[key] = true
    M(P.C.OPEN, layer, k)
  end
  M(P.C.DRAW_PRIORITY, layer, k, priority, true)
end

-- a card from its own sprites: the plate in the slot's position colour, the player's face
local function sprite_card(slot, card)
  local L, S = P.LAYER.CARD, P.SPRITE_CARD
  for _, node in ipairs(S.NODES_OFF) do
    M(P.C.NODE_VISIBLE, L, node, false, slot)
  end
  for _, mesh in ipairs(S.MESHES_OFF) do
    M(P.C.MESH_VISIBLE, L, mesh, false, slot)
  end
  local plate = S.PLATE_SLOT
  for _, entry in ipairs(S.PLATES) do
    if math.floor((card.position or 0) / entry[1]) % 2 == 1 then
      plate = entry[2]
      break
    end
  end
  M(P.C.SPRITE, L, S.TEXTURE, plate, S.PLATE_SLOT, 0, slot)
  M(P.C.MESH_VISIBLE, L, S.PLATE, true, slot)
  M(P.C.RESET_FACE, L, slot, S.FACE_SLOT)
  if card.handle ~= nil then
    M(P.C.FACE, L, slot, false, S.FACE, S.FACE_SLOT, card.handle, 0, 0, 0, false, false, 0)
  else
    local chara = F(P.C.CHARA_OF_PARAM, card.chara)
    if type(chara) ~= "number" or chara == 0 then
      chara = card.chara
    end
    M(P.C.FACE, L, slot, false, S.FACE, S.FACE_SLOT, 0, 0, chara, 0, false, true)
  end
  M(P.C.MESH_VISIBLE, L, S.FACE, true, slot)
end

-- one card: the game's fill (its own sprites when refused), the extra pieces off (again when its instance is built:
-- OnOpenLayer)
local function fill_card(slot)
  local card = P.cards[slot]
  if card == nil then
    M(P.C.VISIBLE, P.LAYER.CARD, slot, false)
    return
  end
  M(P.C.VISIBLE, P.LAYER.CARD, slot, true)
  name_card(slot)
  pcall(SetDisableForceCharaInvalidUseTarget)
  local filled
  if card.handle ~= nil then
    filled = M(P.C.FILL_CARD, card.fill)
  else
    filled = M(P.C.FILL_MEMBER_CARD, P.LAYER.CARD, slot, card.chara, true, false, card.position, 0, card.level,
      card.captain, false, card.kit, card.uniform)
  end
  if filled == false then
    sprite_card(slot, card)
  end
  pcall(SetEnableForceCharaInvalidUseTarget)
  local logged = P.source .. ":" .. slot
  if not P.logged[logged] then
    P.logged[logged] = true
    log("slot", slot, card.handle ~= nil and "dock" or "chronicle", "fill", tostring(filled), "position", card.position)
  end
  for _, mesh in ipairs(P.CARD_HIDE) do
    M(P.C.MESH_VISIBLE, P.LAYER.CARD, mesh, false, slot)
  end
  M(P.C.SCALE, P.LAYER.CARD, P.LAYOUT.CARD_SCALE, P.LAYOUT.CARD_SCALE, 1, slot)
  place(P.LAYER.CARD, slot)
  M(P.C.DRAW_PRIORITY, P.LAYER.CARD, slot, P.LAYOUT.PRIORITY_CARD, true)
  M(P.C.VISIBLE, P.LAYER.CARD, slot, true)
  P.Mark(slot, card.offender == true)
end

-- the red «!» on a starter who breaks the focused row's challenge
function P.Mark(slot, on)
  if instances(P.LAYER.MARK) <= slot then
    return
  end
  if not on then
    if P.opened[P.LAYER.MARK .. ":" .. slot] then
      M(P.C.VISIBLE, P.LAYER.MARK, slot, false)
    end
    return
  end
  local A = P.LAYOUT
  local b = P.base[P.LAYER.CARD .. ":" .. slot]
  if b == nil then
    return
  end
  open(P.LAYER.MARK, slot, A.PRIORITY_MARK)
  M(P.C.SCALE, P.LAYER.MARK, A.MARK_SCALE, A.MARK_SCALE, 1, slot)
  P.base[P.LAYER.MARK .. ":" .. slot] = {b[1] + A.MARK_X * A.CARD_SCALE, b[2] + A.MARK_Y * A.CARD_SCALE}
  place(P.LAYER.MARK, slot)
  M(P.C.VISIBLE, P.LAYER.MARK, slot, true)
end

-- a text line: `s` at `scale`, centred on (cx, cy) (screen px); plate = the corner button's plate behind it
local function text_line(k, s, scale, cx, cy, plate)
  local L = P.LABEL
  open(P.LAYER.TEXT, k, P.LAYOUT.PRIORITY_TEXT)
  M(P.C.MESH_VISIBLE, P.LAYER.TEXT, L.PLATE, plate == true, k)
  M(P.C.MESH_VISIBLE, P.LAYER.TEXT, L.PLATE_ADD, false, k)
  if not plate then
    M(P.C.NODE_SCALE, P.LAYER.TEXT, k, L.TEXT_NODE, L.TEXT_BOX_WIDTH, L.TEXT_BOX_HEIGHT)
  end
  M(P.C.SCALE, P.LAYER.TEXT, 1, 1, 1, k)
  M(P.C.TEXT, P.LAYER.TEXT, L.TEXT_NODE, s, k)
  M(P.C.SCALE, P.LAYER.TEXT, scale, scale, 1, k)
  local x
  if plate then
    x = cx - (L.PLATE_LEFT + L.PLATE_WIDTH / 2) * scale   -- the plate centred, the text at its left as retail
  else
    local width = M(P.C.TEXT_SIZE, P.LAYER.TEXT, k, L.TEXT_NODE)   -- the game's measure (scale 1)
    if type(width) ~= "number" or width <= 0 then
      width = text_width(s)
    end
    x = cx - width * scale / 2 - L.TEXT_LEFT * scale
  end
  P.base[P.LAYER.TEXT .. ":" .. k] = {x, -cy - L.TEXT_MID_Y * scale}
  place(P.LAYER.TEXT, k)
  M(P.C.VISIBLE, P.LAYER.TEXT, k, s ~= "")
end

function P.Hide()
  if not P.shown then
    return
  end
  P.shown = false
  M(P.C.VISIBLE, P.LAYER.PITCH, 0, false)
  for slot = 0, P.STARTERS - 1 do
    M(P.C.VISIBLE, P.LAYER.CARD, slot, false)
  end
  M(P.C.VISIBLE, P.LAYER.TEXT, P.TEXT_FORMATION, false)
  M(P.C.VISIBLE, P.LAYER.TEXT, P.TEXT_BUTTON, false)
  for slot = 0, P.STARTERS - 1 do
    P.Mark(slot, false)
  end
end

-- the band's content, from the focused row's team as it is now
function P.Draw()
  local team = VRFW_RBC_PanelBandTop ~= nil and P.ReadFocusedTeam() or nil
  if team == nil then
    P.source = nil
    return P.Hide()
  end
  P.source = team.key
  local count = 0
  for _ in pairs(team.starters) do
    count = count + 1
  end
  log("draw", team.key, "formation", team.formation, team.name, "starters", count)
  local A, G = P.LAYOUT, P.PITCH
  local top = VRFW_RBC_PanelBandTop(P.BAND_ID)
  local cx = VRFW_RBC.GEOMETRY.PANEL_MID_X
  -- the formation name
  text_line(P.TEXT_FORMATION, team.name, A.NAME_SCALE, cx, top + A.TOP_GAP + A.NAME_HEIGHT / 2, false)
  -- the pitch: its centre locator at (cx, cy)
  local pitch_top = top + A.TOP_GAP + A.NAME_HEIGHT + A.NAME_GAP
  local sx, sy = A.PITCH_SCALE_X, A.PITCH_SCALE_Y
  local cy = pitch_top + (G.FIELD_TOP_Y - G.CENTRE_Y) * sy
  open(P.LAYER.PITCH, 0, A.PRIORITY_PITCH)
  M(P.C.SCALE, P.LAYER.PITCH, sx, sy, 1, 0)
  P.base[P.LAYER.PITCH .. ":0"] = {cx - G.CENTRE_X * sx, -cy - G.CENTRE_Y * sy}
  place(P.LAYER.PITCH, 0)
  M(P.C.VISIBLE, P.LAYER.PITCH, 0, true)
  -- the starters
  P.cards = team.starters
  for slot = 0, P.STARTERS - 1 do
    local rx, ry = P.SlotOffset(team.formation, slot)
    P.base[P.LAYER.CARD .. ":" .. slot] = {cx + rx * sx, -cy + ry * sy}
    open(P.LAYER.CARD, slot, A.PRIORITY_CARD)
    fill_card(slot)
  end
  -- the button
  local by = pitch_top + G.FIELD_HEIGHT * sy + A.PITCH_GAP + A.BUTTON_HEIGHT / 2
  local label = F(P.C.TEXT_GET, P.BUTTON_TEXT)
  text_line(P.TEXT_BUTTON, type(label) == "string" and label or "", A.BUTTON_SCALE, cx, by, true)
  local L = P.LABEL
  P.button = {x = cx, y = by, half_w = L.PLATE_WIDTH * A.BUTTON_SCALE / 2, half_h = L.PLATE_HEIGHT * A.BUTTON_SCALE / 2}
  P.click_prev = true   -- a click counts from its press: the one that opened the menu must be released first
  P.shown = true
end

-- the board opens the team dock: the menu closes with the retail «Plantilla de equipo» item
function P.OpenTeamDock()
  local L = VRFW_RBC.L
  if not P.shown or L.flag or L.flag2 then
    return false
  end
  funcLuaCommand(P.C.SE, P.C.SE_DECIDE)
  P.Hide()
  pcall(SetupButtonGuide)
  funcLuaCommand(P.C.P_CLEAR, P.RESULT)
  funcLuaCommand(P.C.P_SET, P.RESULT, 0, P.ITEM_TEAM_DOCK, 1)
  funcLuaCommand(P.C.CLOSE_MENU, P.MENU)
  L.flag = true
  return true
end

-- a mouse click on the button (ENTER_CLICK without ENTER: not Enter / A), on its press
local function button_clicked()
  local held = funcLuaCommand(P.C.CHECK_INPUT, P.C.MENU_CTRL, P.C.ENTER_CLICK) == true
    and funcLuaCommand(P.C.CHECK_INPUT, P.C.MENU_CTRL, P.C.ENTER) ~= true
  local pressed = held and not P.click_prev
  P.click_prev = held
  if not pressed or P.button == nil then
    return false
  end
  local mx, my = M(P.C.POINTER)
  if type(mx) ~= "number" or type(my) ~= "number" then
    return false
  end
  local dx, dy = 0, 0
  if VRFW_RBC_PanelShift ~= nil then
    dx, dy = VRFW_RBC_PanelShift()
  end
  local b = P.button
  return math.abs(mx - (b.x + dx)) <= b.half_w and math.abs(my - (b.y - dy)) <= b.half_h
end

-- the focused row changed (polled: the list's first focus is set without OnChangeFocus): its battle's lineup when the
-- team or the challenge differs
function P.FollowFocus()
  local index = M(P.C.FOCUS_GET, P.ROWS)
  if index == P.row then
    return
  end
  P.row = index
  local team = P.ReadFocusedTeam()
  if team == nil or team.key ~= P.source then
    P.Draw()
  end
end

function P.Step()
  if P.pending then
    P.pending = false
    if VRFW_RBC.L.flag then
      return
    end
    P.row = M(P.C.FOCUS_GET, P.ROWS)
    P.Draw()
    return
  end
  if not P.shown then
    return
  end
  if not VRFW_RBC.L.flag then
    P.FollowFocus()
  end
  local dx, dy = 0, 0
  if VRFW_RBC_PanelShift ~= nil then
    dx, dy = VRFW_RBC_PanelShift()
  end
  if P.shift == nil or P.shift[1] ~= dx or P.shift[2] ~= dy then
    P.shift = {dx, dy}
    place(P.LAYER.PITCH, 0)
    for slot = 0, P.STARTERS - 1 do
      place(P.LAYER.CARD, slot)
      place(P.LAYER.MARK, slot)
    end
    place(P.LAYER.TEXT, P.TEXT_FORMATION)
    place(P.LAYER.TEXT, P.TEXT_BUTTON)
  end
  if button_clicked() then
    P.OpenTeamDock()
  end
end

-- the handlers on the command menu `stem`; owns(kind) = this mod sizes the panel of that piece kind
function P.Register(stem, owns)
  if VRFW_Host == nil then
    return
  end
  local id = "chronicle_deluxe.lineup"
  -- with BetterUI (clean_hud) the card object uses its compact formation layout (content\menus\team_lineup.toml,
  -- if_mod); its compact-card graft (soccer_common, every menu VM) then hides the name and level of the layers listed
  -- in EVT_FC_EXTRA, its public hook for other mods' card layers. Without BetterUI the table is never read.
  EVT_FC_EXTRA = EVT_FC_EXTRA or {}
  EVT_FC_EXTRA[P.LAYER.CARD] = true
  VRFW_Host.on(stem, "OnInit", {id = id, phase = "before", fn = function()
    reset()
  end})
  -- the panel is placed: the band, then the drawing on the next Step (the layers open outside the setup callback)
  VRFW_Host.on(stem, "VRFW_RBC_ListLayer", {id = id, phase = "after", fn = function(r, layer, kind, rows)
    P.kind = kind
    P.on = owns(kind) and VRFW_RBC_PanelBand ~= nil and layers_ready()
    if P.on then
      VRFW_RBC_PanelBand(P.BAND_ID, P.BAND_HEIGHT, P.BAND_ORDER)
      P.pending = true
    end
  end})
  -- a card instance is set up: the soccer card's name setting (the game's fills need it)
  VRFW_Host.on(stem, "OnSetupLayer", {id = id, phase = "after", fn = function(r, a1, a2)
    if a1 == P.LAYER.CARD and type(a2) == "number" and a2 < P.STARTERS then
      name_card(a2)
    end
  end})
  -- an instance is built: its draw priority again, a card's fill again
  VRFW_Host.on(stem, "OnOpenLayer", {id = id, phase = "after", fn = function(r, a1, a2)
    if not P.shown or type(a2) ~= "number" then
      return
    end
    if a1 == P.LAYER.CARD and a2 < P.STARTERS then
      M(P.C.DRAW_PRIORITY, a1, a2, P.LAYOUT.PRIORITY_CARD, true)
      fill_card(a2)
    elseif a1 == P.LAYER.PITCH then
      M(P.C.DRAW_PRIORITY, a1, a2, P.LAYOUT.PRIORITY_PITCH, true)
    elseif a1 == P.LAYER.TEXT then
      M(P.C.DRAW_PRIORITY, a1, a2, P.LAYOUT.PRIORITY_TEXT, true)
    end
  end})
  -- another row focused: its battle's lineup (redrawn only when the team changes)
  VRFW_Host.on(stem, "OnChangeFocus", {id = id, phase = "after", fn = function(r, a1)
    if a1 ~= P.ROWS or not P.on or P.pending or VRFW_RBC.L.flag then
      return
    end
    P.FollowFocus()
  end})
  VRFW_Host.on(stem, "Step", {id = id, phase = "after", fn = function()
    if P.on then
      P.Step()
    end
  end})
  VRFW_Host.on(stem, "OnFunction", {id = id, phase = "before", fn = function(a1)
    if a1 ~= P.FUNCTION_TEAM_DOCK then
      return
    end
    if P.on then
      P.OpenTeamDock()
    end
    return VRFW_Host.HALT
  end})
  -- the menu closes (a row decided, Back): the band's pieces go with it
  VRFW_Host.on(stem, "OnDecideFocus", {id = id, phase = "before", fn = function()
    P.Hide()
  end})
  VRFW_Host.on(stem, "OnBack", {id = id, phase = "before", fn = function()
    P.Hide()
  end})
end
local K = ChronicleDeluxe.Command

-- kind 1 = a gate piece; no set declared = every row
function K.Rows(rows, kind)
  local s = VRFW_MatchDifficulty ~= nil and VRFW_MatchDifficulty.Set(kind == 1 and "gate" or "route") or nil
  if s == nil or rows == nil then
    return rows
  end
  local keep = {}
  for i = 1, #rows do
    if s[rows[i].difficultyType] then
      keep[#keep + 1] = rows[i]
    end
  end
  return keep
end

-- per list layer kind (0 normal, 1 gate): the panel quad and its retail size (layouts vsroute01_15c / 15d, v7.1.2)
K.PANEL = {
  [0] = {node = 785322415 --[[_list_base01]], width = 700, height = 644, slots = 8},
  [1] = {node = 3083223061 --[[_list_base02]], width = 700, height = 472, slots = 5}
}
K.ROW_HEIGHT = 70
K.NODE_SCALE = 2885415772         -- (layer, instance, node, width, height): a quad's size in px

function K.FitPanel(layer, kind, rows, extra)
  local p = K.PANEL[kind]
  if p == nil or rows == nil or rows < 1 then
    return
  end
  if rows > p.slots then
    rows = p.slots
  end
  funcLuaMenuCommand(K.NODE_SCALE, layer, 0, p.node, p.width, p.height - K.ROW_HEIGHT * (p.slots - rows) + (extra or 0))
end

-- this mod fits the panel (not Inazuma Fantasy's redesign, the mod's difficulty set is declared, and not a framework
-- service's piece: a gacha node keeps its one command row, no lineup, no team level, no «Plantilla de equipo»)
function K.OwnsPanel(kind)
  return EVT_ChrFrameFit == nil and VRFW_MatchDifficulty ~= nil
    and VRFW_MatchDifficulty.Set(kind == 1 and "gate" or "route") ~= nil
    and not (VRFW_RBC_ServicePiece ~= nil and VRFW_RBC_ServicePiece())
end

if VRFW_Host ~= nil then
  VRFW_Host.on("vs_route_town_command_select_menu", "VRFW_RBC_Rows", {id = "chronicle_deluxe.board", phase = "around",
    fn = function(nxt, rows, kind, slot)
      return nxt(K.Rows(rows, kind), kind, slot)
    end})
  VRFW_Host.on("vs_route_town_command_select_menu", "VRFW_RBC_ListLayer", {id = "chronicle_deluxe.panel_fit",
    phase = "after", fn = function(r, layer, kind, rows)
      if K.OwnsPanel(kind) then
        K.FitPanel(layer, kind, rows, VRFW_RBC ~= nil and VRFW_RBC.panel.extra or 0)
      end
    end})
  VRFW_Host.on("vs_route_town_command_select_menu", "VRFW_RBC_PanelExtra", {id = "chronicle_deluxe.panel_band",
    phase = "after", fn = function(r, layer, kind, rows, extra)
      if layer ~= nil and K.OwnsPanel(kind) then
        K.FitPanel(layer, kind, rows, extra)
      end
    end})
  ChronicleDeluxe.Lineup.Register("vs_route_town_command_select_menu", K.OwnsPanel)
end
